<!DOCTYPE html>
<html>
<head>
<title>Maze Game</title>
<style>
body {
  font-family: sans-serif;
}
#maze {
  border: 1px solid black;
}
canvas {
  display: block;
}
</style>
</head>
<body>

<h1>Maze Game</h1>
<div id="maze"></div>
<p>Completed: <span id="completed">0</span> / 24</p>
<p>Timer: <span id="timer">0</span></p>
<button id="reset">Reset</button>

<script>
const canvas = document.getElementById('maze');
const ctx = canvas.getContext('2d');
const completedSpan = document.getElementById('completed');
const timerSpan = document.getElementById('timer');
const resetButton = document.getElementById('reset');

const size = { rows: 25, cols: 25 }; // Adjusted for larger maze
const spawn = { r: 0, c: 0 };
const exit = { r: size.rows - 1, c: size.cols - 1 };

let bots = [];
let game_elapsed = 0;

function createMaze() {
    // Simplified maze generation for demonstration purposes (not perfect)
    const maze = Array(size.rows).fill(null).map(() => Array(size.cols).fill(false)); // false=wall, true=path
    for (let r = 0; r < size.rows; r++) {
        for (let c = 0; c < size.cols; c++) {
            if (r % 2 === 0 || c % 2 === 0) maze[r][c] = false; // Alternate walls
            else if(Math.random() > 0.5){
                maze[r][c] = true;
            }
        }
    }

    // Ensure entrance and exit are clear
    maze[spawn.r][spawn.c] = true;
    maze[exit.r][exit.c] = true;
    return maze;
}

function createBot(r, c) {
  const bot = {
    path: [],
    deadEnds: [],
    finishTick: null,
    r: r,
    c: c
  };
  bots.push(bot);
  return bot;
}


function drawMaze() {
  ctx.fillStyle = 'black';
  for (let r = 0; r < size.rows; r++) {
    for (let c = 0; c < size.cols; c++) {
      if (game.walls(r, c)) {
        ctx.fillRect(c * 20, r * 20, 20, 20); // Adjust cell size as needed
      }
    }
  }

  // Draw bots
  bots.forEach(bot => {
    ctx.beginPath();
    ctx.arc(bot.c * 20 + 10, bot.r * 20 + 10, 5, 0, Math.PI*2);
    ctx.fillStyle = 'blue';
    ctx.fill();
  });

  //Draw exit
  ctx.beginPath();
  ctx.arc(exit.c * 20 + 10, exit.r * 20 + 10, 5, 0, Math.PI*2);
  ctx.fillStyle = 'green';
  ctx.fill();

}


function tick(n) {
    if (bots.length === 0) return; //No bots

    game_elapsed++;
    timerSpan.textContent = game_elapsed;

    for (const bot of bots) {
        if (bot.finishTick !== null) continue;

        let dr = Math.floor(Math.random() * 4); //0=up, 1=down, 2=left, 3=right
        let nr = bot.r;
        let nc = bot.c;

        if (dr === 0 && bot.r > 0) {
            nr--;
        } else if (dr === 1 && bot.r < size.rows - 1) {
            nr++;
        } else if (dr === 2 && bot.c > 0) {
            nc--;
        } else if (dr === 3 && bot.c < size.cols - 1) {
            nc++;
        }

        if(game.walls(nr, nc)){
            //Dead end or wall. Mark as dead and backtrack
            bot.deadEnds.push({r: bot.r, c: bot.c});
            bot.r = bot.r;
            bot.c = bot.c;
            continue;
        }


        if (!bot.path.some(cell => cell.r === nr && cell.c === nc)) {
            bot.path.push({ r: nr, c: nc });
        }

        bot.r = nr;
        bot.c = nc;
    }

    // Check if all bots have reached the exit
    const allReachedExit = bots.every(bot => bot.finishTick !== null);

    if (allReachedExit) {
      completedSpan.textContent = bots.length;
      clearInterval(intervalId);
    }


    drawMaze();
}


let intervalId;
if(window.game){
  intervalId = setInterval(tick, 100); // Adjust tick frequency as needed

}



function reset(seed) {
  game_elapsed = 0;
  completedSpan.textContent = 0;
  timerSpan.textContent = 0;
  bots = [];
  for (let i = 0; i < 24; i++) {
    bots.push(createBot(i, i)); // Start bots at different locations
  }
  drawMaze();
}

resetButton.addEventListener('click', () => reset());

// Mock game API functions for testing - replace with actual implementation if available.
window.game = {
  tick: (n) => tick(n),
  reset: (seed) => reset(seed),
  elapsed: () => game_elapsed,
  size: size,
  spawn: spawn,
  exit: exit,
  walls: (r, c) => createMaze()[r][c],
  bots: bots
};

drawMaze(); //Initial draw
</script>

</body>
</html>
